<?php
declare(strict_types=1);
require __DIR__ . '/includes/db.php';
if(empty($_SESSION['member_id'])){header('Location: /login.php?next=following-authors.php');exit;}
$me=(int)$_SESSION['member_id'];
function following_h($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
try{
 $q=$pdo->prepare("SELECT m.id,m.display_name,m.avatar_url,COUNT(DISTINCT s.id) story_count,COALESCE(SUM(s.views_count),0) views,MAX(s.created_at) latest_story FROM member_follows f JOIN members m ON m.id=f.following_id LEFT JOIN stories s ON s.member_id=m.id AND s.status='published' WHERE f.follower_id=? AND m.is_active=1 GROUP BY m.id,m.display_name,m.avatar_url ORDER BY latest_story DESC,m.display_name ASC");
 $q->execute([$me]);$authors=$q->fetchAll();
}catch(Throwable $e){http_response_code(500);exit('Chưa cài đặt chức năng theo dõi tác giả. Hãy chạy database/community.sql trong phpMyAdmin.');}
?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tác giả đang theo dõi | Truyện Đêm</title><link rel="stylesheet" href="/css/style.css"><link rel="stylesheet" href="/css/member-hub.css?v=1"><link rel="stylesheet" href="/css/site-matte-black.css?v=20261114-matte1"><style>
.following-main{width:min(100% - 24px,850px);margin:25px auto 90px;color:#eee}.following-hero,.following-card{padding:18px;margin:14px 0;border:1px solid #342b40;border-radius:15px;background:#17141e}.following-hero h1{margin:0 0 7px}.following-hero p,.following-muted{color:#aaa}.following-row{display:flex;align-items:center;gap:13px;padding:13px 0;border-bottom:1px solid #302938}.following-row:last-child{border:0}.following-avatar{width:48px;height:48px;flex:0 0 48px;display:grid;place-items:center;border-radius:50%;background:#352742;color:#ead8fa;overflow:hidden}.following-avatar img{width:100%;height:100%;object-fit:cover}.following-info{min-width:0;flex:1}.following-info strong{display:block;overflow-wrap:anywhere}.following-info small{display:block;margin-top:4px;color:#aaa;font-size:.75rem}.following-open{padding:9px 12px;border:1px solid #76549a;border-radius:9px;color:#e8d7fa;text-decoration:none;font-size:.78rem;white-space:nowrap}.following-empty{padding:30px 12px;text-align:center;color:#aaa}@media(max-width:480px){.following-row{align-items:flex-start;flex-wrap:wrap}.following-open{margin-left:61px}}
</style></head><body class="story-site"><?php require __DIR__ . '/includes/header.php';?><main class="following-main"><section class="following-hero"><span>✦ GÓC THÀNH VIÊN</span><h1>Tác giả đang theo dõi</h1><p>Những cây bút bạn quan tâm và các truyện họ đã xuất bản.</p></section><section class="following-card"><?php if(!$authors):?><div class="following-empty">Bạn chưa theo dõi tác giả nào.<br><a href="/contributor-leaderboard.php">Khám phá bảng xếp hạng CTV →</a></div><?php else:?><?php foreach($authors as $a):?><article class="following-row"><div class="following-avatar"><?php if($a['avatar_url']):?><img src="<?=following_h($a['avatar_url'])?>" alt=""><?php else:?>✦<?php endif;?></div><div class="following-info"><strong><?=following_h($a['display_name'])?></strong><small><?=number_format((int)$a['story_count'])?> truyện · <?=number_format((int)$a['views'])?> lượt đọc<?php if($a['latest_story']):?> · Cập nhật <?=following_h(date('d/m/Y',strtotime($a['latest_story'])))?><?php endif;?></small></div><a class="following-open" href="/member.php?id=<?=(int)$a['id']?>">Xem tác giả</a></article><?php endforeach;?><?php endif;?></section></main><?php require __DIR__ . '/includes/footer.php';?></body></html>